import{_ as s,l,o as e,c as i,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"单周期数据通路","description":"","frontmatter":{"title":"单周期数据通路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/single-cycle-datapath.md","filePath":"cs/single-cycle-datapath.md","lastUpdated":1789023840000}'),h={name:"cs/single-cycle-datapath.md"};function _(A,a,P,m,u,C){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="单周期数据通路" tabindex="-1">单周期数据通路 <a class="header-anchor" href="#单周期数据通路" aria-label="Permalink to &quot;单周期数据通路&quot;">​</a></h1><div class="epigraph"><p>一条指令在一个时钟周期内走完取指、译码、执行、访存、写回；周期长度等于最长那条路径。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/register-file">寄存器堆</a>提供了双读单写口。ALU、MUX、内存、PC 计数器此前都已有。本课不重做 6T 单元，也不从流水线五级另起。缺口是：<strong>把积木接成一台能跑 RV32I 子集的机器</strong>，并且规定一拍一条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>各块功能已知，还没有一张总图：PC 出地址取指令；指令字段进堆与立即数拼接；ALUSrc 在寄存器与立即数之间选；ALU 算；MemRead/MemWrite 访问数据存储器；MemtoReg 在 ALU 结果与读出数据之间选，写回堆；分支逻辑改 PC。缺口是这条组合路径外加 PC 与堆的边沿更新。</p><p>控制信号本课先当输入端口；下一课用真值表驱动它们。</p><h3 id="单周期不是「延迟槽里的单条」" tabindex="-1">单周期不是「延迟槽里的单条」 <a class="header-anchor" href="#单周期不是「延迟槽里的单条」" aria-label="Permalink to &quot;单周期不是「延迟槽里的单条」&quot;">​</a></h3><p>每条指令一个周期，周期必须盖住最慢指令（通常 <code>lw</code>：取指+堆+ALU+数据内存+写回 MUX+\\(t_{su}\\)）。<code>add</code> 也要等这个 \\(T\\)，浪费。这是故意的教学机，用来暴露关键路径；多周期与流水线是后课为修这个浪费。</p><p><span class="marginnote">Patterson/Hennessy 第 4 章先单周期再多周期再流水。指令存储器与数据存储器在图上分开（哈佛口），避免同拍取指又 <code>lw</code> 单口冲突。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 PC、指令存储器、堆、立即数扩展、ALU、数据存储器、若干 MUX、分支加法器。时序元件：PC、寄存器堆写、数据存储器写，同一时钟。组合其余。建立保持按<a href="/cs/setup-hold">前面的课</a>检查最长路径。</p>',11)),(e(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22PC%22%5D%20--%3E%20IM%5B%22%E5%8F%96%E6%8C%87%22%5D%0A%20%20IM%20--%3E%20RF%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%22%5D%0A%20%20RF%20--%3E%20ALU%5B%22ALU%22%5D%0A%20%20ALU%20--%3E%20DM%5B%22%E6%95%B0%E6%8D%AE%E5%AD%98%E5%82%A8%E5%99%A8%22%5D%0A%20%20DM%20--%3E%20WB%5B%22%E5%86%99%E5%9B%9E%20MUX%22%5D%0A%20%20WB%20--%3E%20RF%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>功能上 RV32I 的核心指令都能走完。性能上 CPI=1，但 \\(T\\) 很大，IPC 的墙钟时间差。后课流水线把同一张图切成多拍重叠；结构冒险来自本课已经分开的指令/数据口是否合并。</p><p><code>jal</code> 要把 PC+4 写进 <code>rd</code>，数据通路需一条回写 PC+4 的 MUX 输入，容易漏画。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现异常、不实现缓存。数据存储器仍是理想组合读、同步写的教学 SRAM。不把超标量双发射提前。</p><p>后课默认：单周期图上的控制线是下一课真值表的输出；硬件在一拍内完成一条指令。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单周期把取指到写回放进同一 \\(T\\)；\\(T\\) 由最慢指令定。</li><li>积木：PC、双存储器口、堆、ALU、MUX。</li><li>控制尚未生成；CPI=1 不是最快墙钟。</li><li>出处：Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const T=s(h,[["render",_]]);export{f as __pageData,T as default};
